-- F21 patch — voided queue-backed workout re-enters CCH when safe.
-- Filename generated by Supabase CLI 3.1.0.

CREATE OR REPLACE FUNCTION public.health_f21_void_workout_session(
  p_session_id uuid,
  p_client_event_id uuid,
  p_reason text
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_session public.health_workout_sessions%ROWTYPE;
  v_reason text;
  v_now timestamptz := clock_timestamp();
  v_queue_position integer;
  v_should_requeue boolean := false;
  v_clean_reason_codes text[];
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;

  v_reason := NULLIF(btrim(p_reason),'');
  IF v_reason IS NULL THEN
    RAISE EXCEPTION 'void reason is required';
  END IF;

  SELECT *
  INTO v_session
  FROM public.health_workout_sessions
  WHERE id=p_session_id
  FOR UPDATE;

  IF v_session.id IS NULL THEN
    RAISE EXCEPTION 'workout session not found';
  END IF;

  IF NOT public.health_can_write_athlete(v_session.athlete_id) THEN
    RAISE EXCEPTION 'not authorized for athlete';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.health_workout_events ev
    WHERE ev.athlete_id=v_session.athlete_id
      AND ev.client_event_id=p_client_event_id
  ) THEN
    RETURN p_session_id;
  END IF;

  IF v_session.record_status='voided' THEN
    RETURN p_session_id;
  END IF;

  IF v_session.status NOT IN ('completed','aborted') THEN
    RAISE EXCEPTION 'open workout cannot be voided from history';
  END IF;

  IF v_session.queue_entry_id IS NOT NULL THEN
    SELECT q.queue_position
    INTO v_queue_position
    FROM public.health_cch_queue_entries q
    WHERE q.id=v_session.queue_entry_id
      AND q.athlete_id=v_session.athlete_id;

    IF v_queue_position IS NOT NULL THEN
      SELECT NOT EXISTS (
        SELECT 1
        FROM public.health_cch_queue_entries q2
        JOIN public.health_workout_sessions s2
          ON s2.queue_entry_id=q2.id
         AND s2.athlete_id=q2.athlete_id
        WHERE q2.athlete_id=v_session.athlete_id
          AND q2.queue_position>v_queue_position
          AND s2.record_status='active'
          AND s2.status IN ('active','paused','completed')
      )
      INTO v_should_requeue;
    END IF;
  END IF;

  UPDATE public.health_workout_sessions
  SET
    record_status='voided',
    voided_at=v_now,
    void_reason=v_reason,
    voided_by_auth_user_id=auth.uid(),
    status=CASE WHEN status='completed' THEN 'aborted' ELSE status END
  WHERE id=p_session_id
    AND athlete_id=v_session.athlete_id;

  IF v_should_requeue AND v_session.queue_entry_id IS NOT NULL THEN
    SELECT
      array_remove(
        array_remove(
          array_remove(q.reason_codes,'WORKOUT_STARTED'),
          'WORKOUT_COMPLETED'
        ),
        'WORKOUT_COMPLETED_PARTIAL'
      )
    INTO v_clean_reason_codes
    FROM public.health_cch_queue_entries q
    WHERE q.id=v_session.queue_entry_id
      AND q.athlete_id=v_session.athlete_id;

    UPDATE public.health_cch_queue_entries q
    SET
      state='queued',
      reason_codes=CASE
        WHEN 'WORKOUT_VOIDED_REQUEUED'=ANY(coalesce(v_clean_reason_codes,'{}'::text[]))
          THEN coalesce(v_clean_reason_codes,'{}'::text[])
        ELSE array_append(
          coalesce(v_clean_reason_codes,'{}'::text[]),
          'WORKOUT_VOIDED_REQUEUED'
        )
      END
    WHERE q.id=v_session.queue_entry_id
      AND q.athlete_id=v_session.athlete_id;
  END IF;

  INSERT INTO public.health_workout_events (
    athlete_id,
    session_id,
    event_type,
    source,
    client_event_id,
    occurred_at,
    payload,
    created_by_auth_user_id
  )
  VALUES (
    v_session.athlete_id,
    p_session_id,
    'session_voided',
    'user',
    p_client_event_id,
    v_now,
    jsonb_build_object(
      'reason',v_reason,
      'previous_status',v_session.status,
      'queue_entry_id',v_session.queue_entry_id,
      'queue_rewound',v_should_requeue,
      'queue_position',v_queue_position
    ),
    auth.uid()
  );

  RETURN p_session_id;
END;
$$;

REVOKE ALL ON FUNCTION public.health_f21_void_workout_session(uuid,uuid,text)
FROM PUBLIC, anon;

GRANT EXECUTE ON FUNCTION public.health_f21_void_workout_session(uuid,uuid,text)
TO authenticated;
